CREATE TABLE IF NOT EXISTS users (id SERIAL PRIMARY KEY,name VARCHAR(120) NOT NULL,email VARCHAR(255) UNIQUE NOT NULL,password_hash TEXT,role VARCHAR(20) DEFAULT 'student',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS courses (id SERIAL PRIMARY KEY,title VARCHAR(200) NOT NULL,language VARCHAR(50),level VARCHAR(50),description TEXT,content TEXT DEFAULT '',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS enrollments (id SERIAL PRIMARY KEY,user_id INT REFERENCES users(id) ON DELETE CASCADE,course_id INT REFERENCES courses(id) ON DELETE CASCADE,progress INT DEFAULT 0,UNIQUE(user_id,course_id));
CREATE TABLE IF NOT EXISTS mock_tests (id SERIAL PRIMARY KEY,user_id INT REFERENCES users(id) ON DELETE CASCADE,language VARCHAR(50),difficulty VARCHAR(30),score INT DEFAULT 0,total INT DEFAULT 0,questions JSONB DEFAULT '[]',answers JSONB DEFAULT '[]',started_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,completed_at TIMESTAMP);
CREATE TABLE IF NOT EXISTS coding_submissions (id SERIAL PRIMARY KEY,user_id INT REFERENCES users(id) ON DELETE CASCADE,language VARCHAR(50),code TEXT,status VARCHAR(50),score INT,feedback TEXT,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS interview_sessions (id SERIAL PRIMARY KEY,user_id INT REFERENCES users(id) ON DELETE CASCADE,interview_type VARCHAR(50),language VARCHAR(50),overall_score INT,transcript JSONB DEFAULT '[]',started_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,ended_at TIMESTAMP);
CREATE TABLE IF NOT EXISTS interview_answers (id SERIAL PRIMARY KEY,session_id INT REFERENCES interview_sessions(id) ON DELETE CASCADE,question TEXT,answer TEXT,score INT,feedback TEXT,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS notes (id SERIAL PRIMARY KEY,user_id INT REFERENCES users(id) ON DELETE CASCADE,title VARCHAR(200),content TEXT,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS learning_events (id SERIAL PRIMARY KEY,user_id INT REFERENCES users(id) ON DELETE CASCADE,event_type VARCHAR(50),topic VARCHAR(120),score INT,metadata JSONB DEFAULT '{}',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
INSERT INTO courses(title,language,level,description,content) SELECT * FROM (VALUES ('C Programming','C','Beginner','Master programming fundamentals, functions, arrays and pointers.','C fundamentals, variables, control flow, functions, arrays, pointers and structures.'),('C++ & DSA','C++','Intermediate','Build strong data structures and algorithmic problem-solving skills.','STL, arrays, strings, linked lists, stacks, queues, trees, graphs and algorithms.'),('Java Programming','Java','Beginner → Advanced','Learn object-oriented Java and build interview-ready skills.','Syntax, OOP, collections, exceptions, streams, concurrency and interview patterns.'),('Python Programming','Python','Beginner → Advanced','Learn Python for development, automation and technical interviews.','Syntax, data structures, functions, OOP, modules, APIs and problem solving.'),('JavaScript','JavaScript','Beginner → Advanced','Build modern web development foundations.','ES6+, DOM, async JavaScript, APIs, React fundamentals and interview questions.'),('SQL','SQL','Beginner → Intermediate','Learn databases and SQL query design for interviews.','SELECT, joins, aggregation, subqueries, indexes and database design.')) AS v(title,language,level,description,content) WHERE NOT EXISTS (SELECT 1 FROM courses);